RECORDS=[]
for path in sorted((OUT/'policy-draft').rglob('*')):
    if not path.is_file(): continue
    rel=path.relative_to(OUT/'policy-draft')
    draft=path.read_text(encoding='utf-8')
    text=draft
    if rel.name=='SKILL.md' and 'alaa-prompting-guide' not in rel.parts:
        for index,(old,new) in enumerate(BODY):
            if old in text:
                text=text.replace(old,new)
                RECORDS.append({'id':f'C{index+1}', 'path':rel.as_posix(),
                    'draft':old, 'final':new, 'equivalence':'Same section, authority, trigger, obligation, exception and reason; wording only; no relocation.'})
    else:
        for index,(old,new) in enumerate(POLICY_WORDING):
            if old in text:
                text=text.replace(old,new)
                RECORDS.append({'id':f'W{index+1}', 'path':rel.as_posix(),
                    'draft':old,'final':new,'equivalence':'Same intended policy delta, predicate set, exception and authority; shorter wording in place.'})
    dest=OUT/'compressed-draft'/rel
    dest.parent.mkdir(parents=True,exist_ok=True)
    dest.write_text(text,encoding='utf-8',newline='\n')

(OUT/'compression-map.json').write_text(json.dumps(RECORDS,indent=2)+'\n')

# A block-level inventory keeps each baseline obligation visible to independent review.
inventory=[]
for path in sorted((OUT/'before').rglob('*.md')):
    rel=path.relative_to(OUT/'before')
    heading=''
    for index,block in enumerate(re.split(r'\n\s*\n',path.read_text(encoding='utf-8')),1):
        if block.startswith('#'): heading=block.splitlines()[0]
        mapped=next((r for r in RECORDS if r['path']==rel.as_posix() and r['draft']==block),None)
        inventory.append({'id':f'{rel.parts[2]}:{rel.name}:{index}', 'path':rel.as_posix(),
            'section':heading,'baseline':block,'compression_id':mapped['id'] if mapped else None,
            'disposition':'wording replacement in compression-map' if mapped else 'retained, or explicit intended-policy delta; compare draft snapshot'})
(OUT/'rule-inventory.json').write_text(json.dumps(inventory,indent=2)+'\n')
print(f'{len(RECORDS)} in-place wording replacements; {len(inventory)} baseline blocks inventoried')
